from a2_reading import L


def S(id, title, prompt, keywords, model):
    return {'id': id, 'title': title, 'prompt': prompt, 'keywords': keywords, 'model': model}


def W(id, title, prompt, points, model, min_words=30):
    return {'id': id, 'title': title, 'prompt': prompt, 'points': points, 'minWords': min_words, 'model': model}


